int main() {
    string s;
    cin >> s;
    vector<pair<char, long long>> runs;
    for (char c : s) {
        if (!runs.empty() && runs.back().first == c) runs.back().second++;
        else runs.push_back({c, 1});
    }
    long long answer = 0;
    for (auto &[c, len] : runs) answer += len * (len - 1) / 2;
    // A whole middle run framed by two equal neighbouring characters.
    for (size_t i = 1; i + 1 < runs.size(); i++)
        if (runs[i - 1].first == runs[i + 1].first) answer++;
