import java.io.*;
import java.util.*;

public class Main {
    static final InputStream is = System.in;
    static final byte[] buf = new byte[1 << 16];
    static int len = 0, ptr = 0;

    static int rb() throws IOException {
        if (ptr == len) {
            len = is.read(buf, 0, buf.length);
            ptr = 0;
            if (len <= 0) return -1;
        }
        return buf[ptr++];
    }

    static String next() throws IOException {
        int c = rb();
        while (c == ' ' || c == '\n' || c == '\r' || c == '\t') c = rb();
        StringBuilder sb = new StringBuilder();
        while (c != -1 && c != ' ' && c != '\n' && c != '\r' && c != '\t') {
            sb.append((char) c);
            c = rb();
        }
        return sb.toString();
    }

    public static void main(String[] args) throws IOException {
        String s = next();
        int n = s.length();
        char[] runChar = new char[n];
        long[] runLen = new long[n];
        int runs = 0;
        for (int i = 0; i < n; i++) {
            char c = s.charAt(i);
            if (runs > 0 && runChar[runs - 1] == c) runLen[runs - 1]++;
            else {
                runChar[runs] = c;
                runLen[runs++] = 1;
            }
        }
        long answer = 0;
        for (int i = 0; i < runs; i++) answer += runLen[i] * (runLen[i] - 1) / 2;
        // A whole middle run framed by two equal neighbouring characters.
        for (int i = 1; i + 1 < runs; i++) if (runChar[i - 1] == runChar[i + 1]) answer++;
        System.out.println(answer);
    }
}

package main

import (
	"bufio"
	"fmt"
	"os"
)

var reader = bufio.NewReaderSize(os.Stdin, 1<<20)

func readToken() string {
	c, err := reader.ReadByte()
	for err == nil && (c == ' ' || c == '\n' || c == '\r' || c == '\t') {
		c, err = reader.ReadByte()
	}
	var tok []byte
	for err == nil && !(c == ' ' || c == '\n' || c == '\r' || c == '\t') {
		tok = append(tok, c)
		c, err = reader.ReadByte()
	}
	return string(tok)
}

func main() {
	s := readToken()
	var runChar []byte
	var runLen []int
	for i := 0; i < len(s); i++ {
		if k := len(runChar); k > 0 && runChar[k-1] == s[i] {
			runLen[k-1]++
		} else {
			runChar = append(runChar, s[i])
			runLen = append(runLen, 1)
		}
	}
	answer := 0
	for _, l := range runLen {
		answer += l * (l - 1) / 2
	}
	// A whole middle run framed by two equal neighbouring characters.
	for i := 1; i+1 < len(runChar); i++ {
		if runChar[i-1] == runChar[i+1] {
			answer++
		}
	}
	fmt.Println(answer)
}
